(function(){
'use strict';
const T=Traditional,P=T.problems,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='logicWorkshopTraditionalV1';
let saved={drafts:{},solved:[]};try{const d=JSON.parse(localStorage.getItem(key)||'null');if(d&&typeof d.drafts==='object'&&d.drafts&&Array.isArray(d.solved))saved=d;}catch{}
let current=Math.max(0,P.findIndex(p=>p.id===saved.current)),mode='boole',draft,undo=[],filter='전체';const solved=new Set(saved.solved.filter(x=>P.some(p=>p.modes.some(m=>p.id+':'+m===x))));
const blank=()=>({shaded:[],groups:[],candidates:[],verdict:'',counter:[],translation:{type:'',direction:''}}),record=()=>P[current].id+':'+mode;
function notify(msg,error=false){$('tradFeedback').textContent=msg;$('tradFeedback').className='tree-feedback '+(error?'error':'success');}
function save(){saved.current=P[current].id;saved.drafts[record()]=draft;saved.solved=[...solved];try{localStorage.setItem(key,JSON.stringify(saved));}catch{notify('브라우저 저장을 사용할 수 없습니다. 현재 세션에서 계속 풀 수 있습니다.',true);}}
function complete(p){return p.modes.every(m=>solved.has(p.id+':'+m));}
function list(){const done=P.filter(complete).length;$('tradSolved').innerHTML=done+'<span> / 10</span>';$('tradProgress').style.width=done*10+'%';$('tradList').innerHTML=P.filter(p=>filter==='전체'||p.category===filter).map(p=>`<button class="problem-item ${p===P[current]?'chosen':''}" data-problem="${p.number-1}" aria-current="${p===P[current]}"><span class="problem-index">${String(p.number).padStart(2,'0')}</span><span><span class="problem-name">${esc(p.title)}</span><span class="problem-meta">9.${p.number<=4?'1':p.number<=8?'2':'3'} · ${p.category}${p.number===7?' · 두 해석':''}</span></span>${complete(p)?'<span class="completion" aria-label="완료">✓</span>':''}</button>`).join('');}
const centers=[[170,140],[310,140],[240,245]],anchors=[[35,330],[106,115],[374,115],[240,91],[240,324],[174,225],[306,225],[240,177]];let svgCount=0;
function venn(p,d,interactive=false){const uid='venn'+(++svgCount),circle=(i)=>`cx="${centers[i][0]}" cy="${centers[i][1]}" r="105"`;let defs=centers.map((_,i)=>`<clipPath id="${uid}in${i}"><circle ${circle(i)}/></clipPath><mask id="${uid}out${i}" maskUnits="userSpaceOnUse" x="0" y="0" width="480" height="365"><rect width="480" height="365" fill="white"/><circle ${circle(i)} fill="black"/></mask>`).join('');
 const parts=T.regions.map(r=>{let part=`<rect width="480" height="365" fill="${d.shaded.includes(r)?'#c5d0bc':'#fafbf7'}" ${interactive?'data-region="'+r+'"':''}/>`;for(let i=0;i<3;i++)part=`<g ${T.inside(r,i)?'clip-path':'mask'}="url(#${uid}${T.inside(r,i)?'in':'out'}${i})">${part}</g>`;return part;}).join('');
 const labels=anchors.map(([x,y],r)=>{const xs=d.groups.map((g,i)=>g.includes(r)?'X'+(i+1)+(g.length>1?'?':''):'').filter(Boolean).join(' ');return `<text x="${x}" y="${y}" class="venn-number">${r}</text><text x="${x}" y="${y+17}" class="venn-x">${esc(xs)}</text>`;}).join('');
 return `<svg viewBox="0 0 480 365" role="img" aria-label="${esc(p.terms.join(', '))}의 벤다이어그램. 음영과 X의 상세 내용은 아래 표와 목록에 있습니다."><defs>${defs}</defs>${parts}<g class="venn-lines">${centers.map((_,i)=>`<circle ${circle(i)} fill="none" stroke="#638052" stroke-width="1.7"/>`).join('')}<text x="140" y="22" class="venn-label">${esc(p.terms[0])}</text><text x="340" y="22" class="venn-label">${esc(p.terms[1])}</text><text x="240" y="362" class="venn-label">${esc(p.terms[2])}</text>${labels}</g></svg>`;
}
function render(){const p=P[current];$('tradVenn').innerHTML=venn(p,draft,true);$('tradRegions').innerHTML=T.regions.map(r=>`<tr><th scope="row">${r}</th><td>${p.terms.map((t,i)=>`<span class="membership">${esc(t)} <b>${T.inside(r,i)?'O':'X'}</b></span>`).join('')}</td><td><input type="checkbox" data-shade="${r}" aria-label="영역 ${r} 음영" ${draft.shaded.includes(r)?'checked':''}></td><td><input type="checkbox" data-candidate="${r}" aria-label="영역 ${r} X 후보" ${draft.candidates.includes(r)?'checked':''} ${draft.shaded.includes(r)?'disabled':''}></td></tr>`).join('');
 $('tradGroups').innerHTML=draft.groups.length?draft.groups.map((g,i)=>`<div class="trad-group"><span><b>X${i+1}</b>: 영역 ${g.join(' 또는 ')}${g.length>1?' 중 적어도 한 곳에 존재':''}</span><button class="text-btn" data-remove="${i}" aria-label="X${i+1} 삭제">삭제</button></div>`).join(''):'<p class="trad-note">아직 X 표시가 없습니다. 전칭 명제만으로 X를 넣어도 되는지 해석을 확인하세요.</p>';
 $('tradVerdict').value=draft.verdict;$('tradCounter').hidden=draft.verdict!=='invalid';$('tradCounterRegions').innerHTML=T.regions.map(r=>`<label class="counter-region"><input type="checkbox" data-counter="${r}" ${draft.counter.includes(r)?'checked':''}> 영역 ${r} · ${esc(T.regionLabel(p,r))}</label>`).join('');$('tradTranslationType').value=draft.translation.type;$('tradTranslationDirection').value=draft.translation.direction;$('tradUndo').disabled=!undo.length;list();}
function change(fn){undo.push(JSON.parse(JSON.stringify(draft)));fn();render();save();$('tradFeedback').className='tree-feedback';}
function load(i,newMode='boole'){current=i;const p=P[i];mode=p.modes.includes(newMode)?newMode:'boole';let d=saved.drafts[record()];draft=d&&Array.isArray(d.shaded)&&Array.isArray(d.groups)&&Array.isArray(d.counter)&&Array.isArray(d.candidates)&&d.translation?JSON.parse(JSON.stringify(d)):blank();undo=[];
 $('tradCategory').textContent=p.category;$('tradTitle').textContent=p.number+'. '+p.title;$('tradPremises').innerHTML=p.premiseText.map(t=>'<li>'+esc(t)+'</li>').join('');$('tradGoal').textContent='∴ '+p.goalText;$('tradSource').textContent='핸드아웃 2 · p.'+p.page+' · 9절 연습문제';$('tradMode').innerHTML=p.modes.map(m=>`<option value="${m}">${m==='boole'?'불(Boole)의 해석':'아리스토텔레스의 해석'}</option>`).join('');$('tradMode').value=mode;
 $('tradModeNote').textContent=(mode==='boole'?'전칭 A·E는 존재를 함축하지 않습니다. I·O는 존재를 함축합니다.':'이 문제에서는 전칭 전제의 주어인 정사각형이 적어도 하나 존재한다고 해석합니다.')+(p.number===7?' 이 문제는 두 해석을 모두 맞히면 완료됩니다. 현재: '+p.modes.map(m=>(m==='boole'?'불':'아리스토텔레스')+(solved.has(p.id+':'+m)?' ✓':' 미완료')).join(' / '):p.number===10?' “저 산인 장소”는 실제로 존재하는 특정 장소 하나인 단일 원소 집합입니다. 그 존재는 문제에서 주어집니다.':'');
 $('tradTranslation').hidden=p.number!==9;$('tradHelp').textContent='';$('tradFeedback').textContent='';$('tradFeedback').className='tree-feedback';render();save();}
function shade(r){if(!draft.shaded.includes(r)&&draft.groups.some(g=>g.length===1&&g[0]===r)){notify('그 영역에 X가 있습니다. 먼저 해당 X 표시를 수정하거나 삭제하세요.',true);return;}change(()=>{if(draft.shaded.includes(r))draft.shaded=draft.shaded.filter(x=>x!==r);else{draft.shaded.push(r);draft.candidates=draft.candidates.filter(x=>x!==r);draft.groups=draft.groups.map(g=>g.filter(x=>x!==r));}});}
$('tradVenn').onclick=e=>{const t=e.target.closest('[data-region]');if(t)shade(Number(t.dataset.region));};$('tradRegions').onchange=e=>{if(e.target.dataset.shade!==undefined)shade(Number(e.target.dataset.shade));else if(e.target.dataset.candidate!==undefined){const r=Number(e.target.dataset.candidate);draft.candidates=e.target.checked?[...draft.candidates,r]:draft.candidates.filter(x=>x!==r);save();}};
$('tradAddX').onclick=()=>{if(!draft.candidates.length)return notify('X가 있을 수 있는 영역을 하나 이상 선택하세요.',true);change(()=>{draft.groups.push([...draft.candidates].sort((a,b)=>a-b));draft.candidates=[];});};$('tradGroups').onclick=e=>{const b=e.target.closest('[data-remove]');if(b)change(()=>draft.groups.splice(Number(b.dataset.remove),1));};
$('tradDiagramCheck').onclick=()=>{try{T.checkDiagram(P[current],mode,draft);notify('✓ 전제만을 정확하게 표시했습니다. 이제 결론이 반드시 따라오는지 판정하세요.');}catch(e){notify(e.message,true);}};
$('tradUndo').onclick=()=>{if(undo.length){draft=undo.pop();render();save();}};$('tradReset').onclick=()=>{if(confirm('현재 해석의 풀이를 지우고 다시 시작할까요?')){delete saved.drafts[record()];load(current,mode);}};
$('tradMode').onchange=e=>load(current,e.target.value);$('tradList').onclick=e=>{const b=e.target.closest('[data-problem]');if(b)load(Number(b.dataset.problem));};$('tradFilter').onchange=e=>{filter=e.target.value;list();};$('tradVerdict').onchange=e=>{draft.verdict=e.target.value;render();save();};$('tradCounterRegions').onchange=e=>{const r=Number(e.target.dataset.counter);draft.counter=e.target.checked?[...draft.counter,r]:draft.counter.filter(x=>x!==r);save();};
for(const id of ['tradTranslationType','tradTranslationDirection'])$(id).onchange=()=>{draft.translation={type:$('tradTranslationType').value,direction:$('tradTranslationDirection').value};save();};
$('tradAnswerForm').onsubmit=e=>{e.preventDefault();try{T.check(P[current],mode,draft,draft.verdict,draft.counter.reduce((m,r)=>m|(1<<r),0),draft.translation);solved.add(record());save();list();notify('✓ 정답입니다. 전제의 벤다이어그램과 판정을 확인했습니다.'+(P[current].number===7&&!complete(P[current])?' 위에서 다른 해석을 선택해 한 번 더 풀어 보세요.':''));if(P[current].number===7)$('tradModeNote').textContent=(mode==='boole'?'불: 전칭 명제는 존재를 함축하지 않습니다.':'아리스토텔레스: 정사각형의 존재를 전제합니다.')+' 완료 상태: '+P[current].modes.map(m=>(m==='boole'?'불':'아리스토텔레스')+(solved.has(record().split(':')[0]+':'+m)?' ✓':' 미완료')).join(' / ');}catch(e){notify(e.message,true);}};
$('tradHint').onclick=()=>{$('tradHelp').textContent=P[current].hint;};
$('tradSolution').onclick=()=>{const p=P[current],d=T.canonical(p,mode),cs=T.countermodels(p,mode);cs.sort((a,b)=>T.regions.filter(r=>T.occupied(a,r)).length-T.regions.filter(r=>T.occupied(b,r)).length);const reason=p.number===7?(mode==='boole'?'정사각형이 없어도 두 전칭 전제는 참일 수 있습니다. 따라서 마름모이면서 직사각형인 대상의 존재는 보장되지 않습니다.':'정사각형이 적어도 하나 존재하고, 그 대상은 마름모이면서 직사각형입니다.') :p.number===9?'“오직 철학자만 현명하다”는 A형, “모든 현명한 사람은 철학자이다”입니다. 과학자이면서 현명한 X는 철학자 집합 안에 놓입니다.':p.number===10?'존재하는 특정 장소 “저 산”은 연기가 있는 장소입니다. 연기가 있는 모든 장소는 불이 있는 장소이므로 저 산에도 불이 있습니다.':cs.length?'전제들을 만족하면서도 결론이 거짓인 배치가 가능합니다.':'전제의 음영과 X만으로 결론이 요구하는 조건이 이미 성립합니다.';
 $('tradHelp').innerHTML='<b>예시 풀이 · '+(cs.length?'타당하지 않음':'타당함')+'</b><p>'+esc(reason)+'</p>'+venn(p,d)+'<p>음영: '+(d.shaded.join(', ')||'없음')+'</p><p>'+d.groups.map((g,i)=>'X'+(i+1)+': 영역 '+g.join(' 또는 ')).join('<br>')+'</p>'+(cs.length?'<p><b>반례:</b> '+T.regions.filter(r=>T.occupied(cs[0],r)).map(r=>'영역 '+r+'에 대상 하나 ('+esc(T.regionLabel(p,r))+')').join('; ')+'. 나머지 영역은 비어 있습니다. 전제는 모두 참, 결론은 거짓입니다.</p>':'')+'<p class="trad-note">예시 풀이는 내 풀이와 완료 기록을 바꾸지 않습니다.</p>';};
$('tradNext').onclick=()=>{const list=P.filter(p=>filter==='전체'||p.category===filter),i=list.indexOf(P[current]);load(list[(i+1)%list.length].number-1);};$('tradDialogClose').onclick=()=>$('tradRulesDialog').close();load(current);
})();
